/// <summary>
/// Logic block used to create a Profit Loss journal
/// </summary>
class MwmsLogicBlockCreateProfitLossJournal extends MwmsLogicBlockjournalsCommon implements TFMLogicBlockDataCollectionInterface
{

}

Method.Source:
public static MwmsLogicBlockCreateProfitLossJournal Construct()
{
    return new MwmsLogicBlockCreateProfitLossJournal();
}

/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A MobReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{

    TFMRegistrationCollectorList	journalList = new TFMRegistrationCollectorList(1,extendedTypeStr(Description),"@MobileWMS:AdjustmentCause","@MobileWMS:AdjustmentCause","@MobileWMS:AdjustmentCause");
    TFMReferenceDataFilterList      inventoryAdjustmentCauseList = this.InventoryAdjustmentCauses();
    refConf = components.getHeaders();

    if (inventoryAdjustmentCauseList.getMap().elements())
    {
        journalList.parmDataTable(methodStr(MwmsLogicBlockCreateProfitLossJournal,InventoryAdjustmentCauses));
        refconf.addCollector(journalList,true);
        refConf.addEmbeddedDataList(methodStr(MwmsLogicBlockCreateProfitLossJournal, InventoryAdjustmentCauses), inventoryAdjustmentCauseList);
    }

    return refconf;
}

/// <summary>
/// Provides the data for inventory adjustment causes used when creating new journals
/// </summary>
/// <returns>A reference data filter list, containing the data used to create the journal</returns>
protected TFMReferenceDataFilterList InventoryAdjustmentCauses()
{
    TFMReferenceDataFilterList	list = new TFMReferenceDataFilterList();
    MapEnumerator				mEnum = MobInventAdjustmentCauses::getAllCauses().getEnumerator();

    while (mEnum.moveNext())
    {
        list.addValue(mEnum.currentKey(),mEnum.currentKey());
    }

    return list;
}

public Set autoCreatedProcesses()
{
    Set ret = super();
    TFMProcess process = TFMProcess::Construct(TFMConstants::CreateProfitLossJournal());
    process.addBlock(this);
    ret.add(process);
    return ret;
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    return null;
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <returns>Returns a MobRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A MobPostResponseData object.</returns>
public TFMPostResponseData post()
{
    TFMPostResponseData         response = TFMPostResponseData::Construct();
    str							description			= docRequest.getFieldValue(extendedTypeStr(description));
    InventJournalName			inventJournalName;
    MobInventAdjustmentCauses	adjCauses			= MobInventAdjustmentCauses::Find(description);

    // Get the name of the profit/loss journal to create
    inventJournalName = InventJournalName::find(adjCauses && adjCauses.InventJournalNameLossProfit ? adjCauses.InventJournalNameLossProfit : MobParameters::find().InventJournalNameLossProfit,true);

    docRequest.addField(extendedTypeStr(JournalNameId),inventJournalName.JournalNameId);
    docRequest.addField(extendedTypeStr(description),adjCauses ? inventJournalName.Description : description);

    inventJournalTable.clear();
    inventJournalTable.JournalType          = inventJournalType::LossProfit;
    inventJournalTable = components.provideDataIfPossible(inventJournalTable);
    inventJournalTable.insert();

    response.parmResponseText("@MobileWMS:ProfitLossJournalcreatedsucessfully");
    return response;
}
